CREATE TABLE purchase_drafts (id BIGINT AUTO_INCREMENT PRIMARY KEY, meal_date DATE NOT NULL, fingerprint CHAR(64) NOT NULL, snapshot_json LONGTEXT NOT NULL, actor VARCHAR(120) NOT NULL, request_key VARCHAR(100) NOT NULL UNIQUE, payload_hash CHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL);
CREATE TABLE draft_lines (id BIGINT AUTO_INCREMENT PRIMARY KEY, draft_id BIGINT NOT NULL, inventory_id BIGINT NOT NULL, suggested_base DECIMAL(20,6) NOT NULL, ordered_base DECIMAL(20,6) NOT NULL, received_base DECIMAL(20,6) NOT NULL DEFAULT 0, display_unit VARCHAR(20) NOT NULL, FOREIGN KEY(draft_id) REFERENCES purchase_drafts(id), FOREIGN KEY(inventory_id) REFERENCES inventory_items(id), UNIQUE(draft_id,inventory_id), CHECK(ordered_base>=0 AND received_base>=0 AND received_base<=ordered_base));
ALTER TABLE stock_lots ADD CONSTRAINT fk_lot_draft_line FOREIGN KEY(draft_line_id) REFERENCES draft_lines(id);
CREATE TABLE guidance_notes (id BIGINT AUTO_INCREMENT PRIMARY KEY, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, kind VARCHAR(30) NOT NULL, note_text TEXT NOT NULL, actor VARCHAR(120) NOT NULL, created_at DATETIME(6) NOT NULL);
